window.officeBundle = {"date":"2026-11-20","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Thus says the One who is high and lifted up, who inhabits eternity, whose name is Holy: \u201cI dwell in the high and holy place, and also with him who is of a contrite and lowly spirit, to revive the spirit of the lowly, and to revive the heart of the contrite.\u201d"},{"line_type":"citation","content":"ISAIAH 57:15"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Dearly beloved, the Scriptures teach us to acknowledge our many sins and offenses, not concealing them from our heavenly Father, but confessing them with humble and obedient hearts that we may obtain forgiveness by his infinite goodness and mercy. We ought at all times humbly to acknowledge our sins before Almighty God, but especially when we come together in his presence to give thanks for the great benefits we have received at his hands, to declare his most worthy praise, to hear his holy Word, and to ask, for ourselves and on behalf of others, those things which are necessary for our life and our salvation. Therefore, draw near with me to the throne of heavenly grace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"Worship the Lord in the beauty of holiness:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"Worship the Lord in the beauty of holiness:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 52"},{"line_type":"subheading","content":"Quid gloriaris?"},{"line_type":"leader","content":"Why do you boast, you tyrant, *","preface":1},{"line_type":"leader","content":"that you can do evil;"},{"line_type":"congregation","content":"Whereas the goodness of God *","preface":2},{"line_type":"congregation","content":"endures all the day long?"},{"line_type":"leader","content":"Your tongue devises wickedness, *","preface":3},{"line_type":"leader","content":"and with lies you cut like a sharp razor."},{"line_type":"congregation","content":"You have loved unrighteousness more than goodness *","preface":4},{"line_type":"congregation","content":"and to utter lies more than truth."},{"line_type":"leader","content":"You have loved to speak all words that hurt, *","preface":5},{"line_type":"leader","content":"O you deceitful tongue."},{"line_type":"congregation","content":"Therefore, God shall destroy you for ever; *","preface":6},{"line_type":"congregation","content":"he shall catch you, and pluck you out of your dwelling, and root you out of the land of the living."},{"line_type":"leader","content":"The righteous also shall see this and fear, *","preface":7},{"line_type":"leader","content":"and shall laugh him to scorn:"},{"line_type":"congregation","content":"\u201cBehold, this is the one who did not take God for his strength, *","preface":8},{"line_type":"congregation","content":"but trusted in the multitude of his riches and relied on his wickedness.\u201d"},{"line_type":"leader","content":"As for me, I am like a green olive tree in the house of God; *","preface":9},{"line_type":"leader","content":"my trust is in the tender mercy of God for ever and ever."},{"line_type":"congregation","content":"I will always give thanks unto you for what you have done, *","preface":10},{"line_type":"congregation","content":"and I will declare your Name among the faithful, for it is good."},{"line_type":"heading","content":"Psalm 53"},{"line_type":"subheading","content":"Dixit insipiens"},{"line_type":"leader","content":"The fool has said in his heart, *","preface":1},{"line_type":"leader","content":"\u201cThere is no God.\u201d"},{"line_type":"congregation","content":"They are corrupt and have become abominable in their wickedness; *","preface":2},{"line_type":"congregation","content":"there is none that does good."},{"line_type":"leader","content":"God looked down from heaven upon the children of men *","preface":3},{"line_type":"leader","content":"to see if there were any who would understand and seek after God."},{"line_type":"congregation","content":"But they have all gone astray; they have altogether become abominable; *","preface":4},{"line_type":"congregation","content":"there is none that does good, no, not one."},{"line_type":"leader","content":"Have they no knowledge, all the workers of evil *","preface":5},{"line_type":"leader","content":"who eat up my people as they would eat bread, and call not upon God?"},{"line_type":"congregation","content":"They were afraid where no fear was, *","preface":6},{"line_type":"congregation","content":"for God has broken the bones of those who besieged you;"},{"line_type":"leader","content":"You have put them to shame, *","preface":7},{"line_type":"leader","content":"because God has rejected them."},{"line_type":"congregation","content":"Oh, that salvation were given unto Israel out of Zion! *","preface":8},{"line_type":"congregation","content":"Oh, that God would deliver his people out of captivity!"},{"line_type":"leader","content":"Then shall Jacob rejoice, *","preface":9},{"line_type":"leader","content":"and Israel shall be glad."},{"line_type":"heading","content":"Psalm 54"},{"line_type":"subheading","content":"Deus, in Nomine"},{"line_type":"leader","content":"Save me, O God, for your Name\u2019s sake, *","preface":1},{"line_type":"leader","content":"and avenge me in your strength."},{"line_type":"congregation","content":"Hear my prayer, O God, *","preface":2},{"line_type":"congregation","content":"and hearken to the words of my mouth."},{"line_type":"leader","content":"For the arrogant have risen up against me, *","preface":3},{"line_type":"leader","content":"and tyrants, who do not have God before their eyes, seek after my life."},{"line_type":"congregation","content":"Behold, God is my helper; *","preface":4},{"line_type":"congregation","content":"the Lord is he who upholds my life."},{"line_type":"leader","content":"He shall repay the evil of my enemies. *","preface":5},{"line_type":"leader","content":"O destroy them in your faithfulness."},{"line_type":"congregation","content":"A freewill offering will I give you, *","preface":6},{"line_type":"congregation","content":"and praise your Name, O L\u1d0f\u0280\u1d05, because it is good."},{"line_type":"leader","content":"For he has delivered me out of all my trouble, *","preface":7},{"line_type":"leader","content":"and my eye has seen the ruin of my enemies."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 14"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the fourteenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_87757712-c66c-5d90-9ff2-2e76ee533445'></span><p><span class=\"cc vnumVis\">14</span>Then said Judith unto them, Hear me now, my brethren, and take this head, and hang it upon the highest place of your walls. <sup>2\u00a0</sup>And so soon as the morning shall appear, and the sun shall come forth upon the earth, take ye every one his weapons, and go forth every valiant man out of the city, and set ye a captain over them, as though ye would go down into the field toward the watch of the Assyrians; but go not down. <sup>3\u00a0</sup>Then they shall take their armour, and shall go into their camp, and raise up the captains of the army of Assur, and shall run to the tent of Holofernes, but shall not find him: then fear shall fall upon them, and they shall flee before your face. <sup>4\u00a0</sup>So ye, and all that inhabit the coast of Israel, shall pursue them, and overthrow them as they go. <sup>5\u00a0</sup>But before ye do these things, call me Achior the Ammonite, that he may see and know him that despised the house of Israel, and that sent him to us as it were to his death. <sup>6\u00a0</sup>Then they called Achior out of the house of Ozias; and when he was come, and saw the head of Holofernes in a man\u2019s hand in the assembly of the people, he fell down on his face, and his spirit failed. <sup>7\u00a0</sup>But when they had recovered him, he fell at Judith\u2019s feet, and reverenced her, and said, Blessed art thou in all the tabernacles of Juda, and in all nations, which hearing thy name shall be astonished. <sup>8\u00a0</sup>Now therefore tell me all the things that thou hast done in these days. Then Judith declared unto him in the midst of the people all that she had done, from the day that she went forth until that hour she spake unto them. <sup>9\u00a0</sup>And when she had left off speaking, the people shouted with a loud voice, and made a joyful noise in their city. <sup>10\u00a0</sup>And when Achior had seen all that the God of Israel had done, he believed in God greatly, and circumcised the flesh of his foreskin, and was joined unto the house of Israel unto this day. <sup>11\u00a0</sup>And as soon as the morning arose, they hanged the head of Holofernes upon the wall, and every man took his weapons, and they went forth by bands unto the straits of the mountain. <sup>12\u00a0</sup>But when the Assyrians saw them, they sent to their leaders, which came to their captains and tribunes, and to every one of their rulers. <sup>13\u00a0</sup>So they came to Holofernes\u2019 tent, and said to him that had the charge of all his things, Waken now our lord: for the slaves have been bold to come down against us to battle, that they may be utterly destroyed. <sup>14\u00a0</sup>Then went in Bagoas, and knocked at the door of the tent; for he thought that he had slept with Judith. <sup>15\u00a0</sup>But because none answered, he opened it, and went into the bedchamber, and found him cast upon the floor dead, and his head was taken from him. <sup>16\u00a0</sup>Therefore he cried with a loud voice, with weeping, and sighing, and a mighty cry, and rent his garments. <sup>17\u00a0</sup>After he went into the tent where Judith lodged: and when he found her not, he leaped out to the people, and cried, <sup>18\u00a0</sup>These slaves have dealt treacherously; one woman of the Hebrews hath brought shame upon the house of king Nabuchodonosor: for, behold, Holofernes lieth upon the ground without a head. <sup>19\u00a0</sup>When the captains of the Assyrians\u2019 army heard these words, they rent their coats and their minds were wonderfully troubled, and there was a cry and a very great noise throughout the camp.<br/></p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 18:24-19:7"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the eighteenth chapter, the twenty-fourth verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_6dc37e73-c279-5e2d-ac52-1f8c16c44959'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Acts-18-24\" id=\"en-AKJV-27582\"><sup class=\"versenum\">24\u00a0</sup>And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus. </span> <span class=\"text Acts-18-25\" id=\"en-AKJV-27583\"><sup class=\"versenum\">25\u00a0</sup>This man was instructed in the way of the Lord; and being fervent in the spirit, he spake and taught diligently the things of the Lord, knowing only the baptism of John. </span> <span class=\"text Acts-18-26\" id=\"en-AKJV-27584\"><sup class=\"versenum\">26\u00a0</sup>And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly. </span> <span class=\"text Acts-18-27\" id=\"en-AKJV-27585\"><sup class=\"versenum\">27\u00a0</sup>And when he was disposed to pass into Achaia, the brethren wrote, exhorting the disciples to receive him: who, when he was come, helped them much which had believed through grace: </span> <span class=\"text Acts-18-28\" id=\"en-AKJV-27586\"><sup class=\"versenum\">28\u00a0</sup>for he mightily convinced the Jews, and that publickly, shewing by the scriptures that Jesus was Christ.</span></p><span data-line-id='secondreading_fed4a0ff-4ce8-5a5f-b133-6666dce84e04'></span> <p class=\"top-1 chapter-2\"><span class=\"text Acts-19-1\" id=\"en-AKJV-27587\"><span class=\"chapternum\">19\u00a0</span>And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples, </span> <span class=\"text Acts-19-2\" id=\"en-AKJV-27588\"><sup class=\"versenum\">2\u00a0</sup>he said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost. </span> <span class=\"text Acts-19-3\" id=\"en-AKJV-27589\"><sup class=\"versenum\">3\u00a0</sup>And he said unto them, Unto what then were ye baptized? And they said, Unto John\u2019s baptism. </span> <span class=\"text Acts-19-4\" id=\"en-AKJV-27590\"><sup class=\"versenum\">4\u00a0</sup>Then said Paul, John verily baptized with the baptism of repentance, saying unto the people, that they should believe on him which should come after him, that is, on Christ Jesus. </span> <span class=\"text Acts-19-5\" id=\"en-AKJV-27591\"><sup class=\"versenum\">5\u00a0</sup>When they heard this, they were baptized in the name of the Lord Jesus. </span> <span class=\"text Acts-19-6\" id=\"en-AKJV-27592\"><sup class=\"versenum\">6\u00a0</sup>And when Paul had laid his hands upon them, the Holy Ghost came on them; and they spake with tongues, and prophesied. </span> <span class=\"text Acts-19-7\" id=\"en-AKJV-27593\"><sup class=\"versenum\">7\u00a0</sup>And all the men were about twelve.</span></p> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Friday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Edmund, King of East Anglia and Martyr, 870"},{"line_type":"leader","content":"Almighty God, you gave your servant Edmund boldness to confess the Name of our Savior Jesus Christ before the rulers of this world, and courage to die for this faith: Grant that we may always be ready to give a reason for the hope that is in us, and to suffer gladly for the sake of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Endurance"},{"line_type":"subheading","content":"Friday"},{"line_type":"leader","content":"Almighty God, whose most dear Son went not up to joy but first he suffered pain, and entered not into glory before he was crucified: Mercifully grant that we, walking in the way of the Cross, may find it none other than the way of life and peace; through Jesus Christ your Son our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"Almighty and everlasting God, who alone works great marvels: Send down upon our clergy and the congregations committed to their charge the life-giving Spirit of your grace, shower them with the continual dew of your blessing, and ignite in them a zealous love of your Gospel; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Glory to God whose power, working in us, can do infinitely more than we can ask or imagine: Glory to him from generation to generation in the Church, and in Christ Jesus for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"EPHESIANS 3:20-21"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"If anyone is in Christ, he is a new creation. The old has passed away; behold, the new has come. All this is from God, who through Christ reconciled us to himself and gave us the ministry of reconciliation."},{"line_type":"citation","content":"2 CORINTHIANS 5:17-18"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Almighty Savior, who at mid-day called your servant Saint Paul to be an apostle to the Gentiles: We pray you to illumine the world with the radiance of your glory, that all nations may come and worship you; for you live and reign with the Father and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"I will thank the Lord for giving me counsel; my heart also chastens me in the night season. I have set the Lord always before me; he is at my right hand, therefore I shall not fall."},{"line_type":"citation","content":"PSALM 16:8-9"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Dearly beloved, the Scriptures teach us to acknowledge our many sins and offenses, not concealing them from our heavenly Father, but confessing them with humble and obedient hearts that we may obtain forgiveness by his infinite goodness and mercy. We ought at all times humbly to acknowledge our sins before Almighty God, but especially when we come together in his presence to give thanks for the great benefits we have received at his hands, to declare his most worthy praise, to hear his holy Word, and to ask, for ourselves and on behalf of others, those things which are necessary for our life and our salvation. Therefore, draw near with me to the throne of heavenly grace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 55"},{"line_type":"subheading","content":"Exaudi, Deus"},{"line_type":"leader","content":"Hear my prayer, O God, *","preface":1},{"line_type":"leader","content":"and hide not yourself from my petition."},{"line_type":"congregation","content":"Give heed to me, and hear me, *","preface":2},{"line_type":"congregation","content":"for I am troubled in my prayer and am tormented,"},{"line_type":"leader","content":"Because of the cry of the enemy, and oppression by the ungodly; *","preface":3},{"line_type":"leader","content":"for they are of a mind to do me great harm, so maliciously are they set against me."},{"line_type":"congregation","content":"My heart is disquieted within me, *","preface":4},{"line_type":"congregation","content":"and the fear of death has fallen upon me."},{"line_type":"leader","content":"Fearfulness and trembling have come upon me, *","preface":5},{"line_type":"leader","content":"and a horrible dread has overwhelmed me."},{"line_type":"congregation","content":"And I said, \u201cOh, that I had wings like a dove, *","preface":6},{"line_type":"congregation","content":"for then would I fly away and be at rest."},{"line_type":"leader","content":"Indeed, then I would get away to a far off place *","preface":7},{"line_type":"leader","content":"and make my dwelling in the wilderness."},{"line_type":"congregation","content":"I would make haste to escape, *","preface":8},{"line_type":"congregation","content":"because of the stormy wind and tempest.\u201d"},{"line_type":"leader","content":"Confuse their speech, O Lord, and divide them, *","preface":9},{"line_type":"leader","content":"for I have seen unrighteousness and strife in the city."},{"line_type":"congregation","content":"Day and night they go about within her walls; *","preface":10},{"line_type":"congregation","content":"trouble and sorrow are in the midst of her."},{"line_type":"leader","content":"Great wickedness is there; *","preface":11},{"line_type":"leader","content":"deceit and guile do not leave her streets."},{"line_type":"congregation","content":"For it is not an enemy who has done me this dishonor, *","preface":12},{"line_type":"congregation","content":"for then I could have borne it;"},{"line_type":"leader","content":"Neither was it my adversary who exalted himself against me, *","preface":13},{"line_type":"leader","content":"for then I would have hidden myself from him."},{"line_type":"congregation","content":"But it was you, my companion, *","preface":14},{"line_type":"congregation","content":"my comrade and my own familiar friend."},{"line_type":"leader","content":"We took sweet counsel together *","preface":15},{"line_type":"leader","content":"and walked in the house of God as friends."},{"line_type":"congregation","content":"Let death come hastily upon them, and let them go down alive into the grave, *","preface":16},{"line_type":"congregation","content":"for there is wickedness in their hearts."},{"line_type":"leader","content":"As for me, I will call upon God, *","preface":17},{"line_type":"leader","content":"and the L\u1d0f\u0280\u1d05 shall save me."},{"line_type":"congregation","content":"In the evening, and morning, and at noonday will I pray and lament, *","preface":18},{"line_type":"congregation","content":"and he shall hear my voice."},{"line_type":"leader","content":"It is he who shall deliver my soul in peace from the battle that is against me, *","preface":19},{"line_type":"leader","content":"for there are many who fight me."},{"line_type":"congregation","content":"God, who endures for ever, shall hear me and bring them down; *","preface":20},{"line_type":"congregation","content":"for they never change, nor do they fear God."},{"line_type":"leader","content":"My familiar friend has laid his hands upon those who were at peace with him, *","preface":21},{"line_type":"leader","content":"and he has broken his covenant."},{"line_type":"congregation","content":"The words of his mouth were softer than butter, yet war was in his heart; *","preface":22},{"line_type":"congregation","content":"his words were smoother than oil, and yet they were drawn swords."},{"line_type":"leader","content":"O cast your burden upon the L\u1d0f\u0280\u1d05, and he shall nourish you, *","preface":23},{"line_type":"leader","content":"and shall not allow the righteous to fall for ever."},{"line_type":"congregation","content":"But as for the bloodthirsty and deceitful, *","preface":24},{"line_type":"congregation","content":"you, O God, shall bring them into the pit of destruction."},{"line_type":"leader","content":"They shall not live out half their days; *","preface":25},{"line_type":"leader","content":"but my trust shall be in you, O L\u1d0f\u0280\u1d05."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 33"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the thirty-third chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_3de1a5a7-ce39-564f-bfb7-fb7e93483905'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-33-1\" id=\"en-AKJV-18281\"><span class=\"chapternum\">33\u00a0</span>Woe to thee that spoilest, and thou wast not spoiled;</span></span><br/><span class=\"text Isa-33-1\">and dealest treacherously, and they dealt not treacherously with thee!</span><br/><span class=\"text Isa-33-1\">when thou shalt cease to spoil, thou shalt be spoiled;</span><br/><span class=\"text Isa-33-1\">and when thou shalt make an end to deal treacherously,</span><br/><span class=\"text Isa-33-1\">they shall deal treacherously with thee.</span><br/><span class=\"text Isa-33-2\" id=\"en-AKJV-18282\"><sup class=\"versenum\">2\u00a0</sup>O <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>, be gracious unto us;</span><br/><span class=\"text Isa-33-2\">we have waited for thee:</span><br/><span class=\"text Isa-33-2\">be thou their arm every morning,</span><br/><span class=\"text Isa-33-2\">our salvation also in the time of trouble.</span><br/><span class=\"text Isa-33-3\" id=\"en-AKJV-18283\"><sup class=\"versenum\">3\u00a0</sup>At the noise of the tumult the people fled;</span><br/><span class=\"text Isa-33-3\">at the lifting up of thyself the nations were scattered.</span><br/><span class=\"text Isa-33-4\" id=\"en-AKJV-18284\"><sup class=\"versenum\">4\u00a0</sup>And your spoil shall be gathered like the gathering of the caterpiller:</span><br/><span class=\"text Isa-33-4\">as the running to and fro of locusts shall he run upon them.</span><br/><span class=\"text Isa-33-5\" id=\"en-AKJV-18285\"><sup class=\"versenum\">5\u00a0</sup>The <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is exalted; for he dwelleth on high:</span><br/><span class=\"text Isa-33-5\">he hath filled Zion with judgment and righteousness.</span><br/><span class=\"text Isa-33-6\" id=\"en-AKJV-18286\"><sup class=\"versenum\">6\u00a0</sup>And wisdom and knowledge shall be</span><br/><span class=\"text Isa-33-6\">the stability of thy times, and strength of salvation:</span><br/><span class=\"text Isa-33-6\">the fear of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is his treasure.</span><br/><span class=\"text Isa-33-7\" id=\"en-AKJV-18287\"><sup class=\"versenum\">7\u00a0</sup>Behold, their valiant ones shall cry without:</span><br/><span class=\"text Isa-33-7\">the ambassadors of peace shall weep bitterly.</span><br/><span class=\"text Isa-33-8\" id=\"en-AKJV-18288\"><sup class=\"versenum\">8\u00a0</sup>The highways lie waste, the wayfaring man ceaseth:</span><br/><span class=\"text Isa-33-8\">he hath broken the covenant, he hath despised the cities,</span><br/><span class=\"text Isa-33-8\">he regardeth no man.</span><br/><span class=\"text Isa-33-9\" id=\"en-AKJV-18289\"><sup class=\"versenum\">9\u00a0</sup>The earth mourneth and languisheth:</span><br/><span class=\"text Isa-33-9\">Lebanon is ashamed and hewn down:</span><br/><span class=\"text Isa-33-9\">Sharon is like a wilderness;</span><br/><span class=\"text Isa-33-9\">and Bashan and Carmel shake off their fruits.</span></p><span data-line-id='firstreading_f261b599-c83c-570c-90fb-01ea6583d50c'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-33-10\" id=\"en-AKJV-18290\"><sup class=\"versenum\">10\u00a0</sup>Now will I rise, saith the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>;</span><br/><span class=\"text Isa-33-10\">now will I be exalted; now will I lift up myself.</span><br/><span class=\"text Isa-33-11\" id=\"en-AKJV-18291\"><sup class=\"versenum\">11\u00a0</sup>Ye shall conceive chaff, ye shall bring forth stubble:</span><br/><span class=\"text Isa-33-11\">your breath, as fire, shall devour you.</span><br/><span class=\"text Isa-33-12\" id=\"en-AKJV-18292\"><sup class=\"versenum\">12\u00a0</sup>And the people shall be as the burnings of lime:</span><br/><span class=\"text Isa-33-12\">as thorns cut up shall they be burned in the fire.</span></p><span data-line-id='firstreading_d9905b34-382b-5627-a247-a00ac34035be'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-33-13\" id=\"en-AKJV-18293\"><sup class=\"versenum\">13\u00a0</sup>Hear, ye that are far off, what I have done;</span><br/><span class=\"text Isa-33-13\">and, ye that are near, acknowledge my might.</span><br/><span class=\"text Isa-33-14\" id=\"en-AKJV-18294\"><sup class=\"versenum\">14\u00a0</sup>The sinners in Zion are afraid;</span><br/><span class=\"text Isa-33-14\">fearfulness hath surprised the hypocrites.</span><br/><span class=\"text Isa-33-14\">Who among us shall dwell with the devouring fire?</span><br/><span class=\"text Isa-33-14\">who among us shall dwell with everlasting burnings?</span><br/><span class=\"text Isa-33-15\" id=\"en-AKJV-18295\"><sup class=\"versenum\">15\u00a0</sup>He that walketh righteously, and speaketh uprightly;</span><br/><span class=\"text Isa-33-15\">he that despiseth the gain of oppressions,</span><br/><span class=\"text Isa-33-15\">that shaketh his hands from holding of bribes,</span><br/><span class=\"text Isa-33-15\">that stoppeth his ears from hearing of blood,</span><br/><span class=\"text Isa-33-15\">and shutteth his eyes from seeing evil;</span><br/><span class=\"text Isa-33-16\" id=\"en-AKJV-18296\"><sup class=\"versenum\">16\u00a0</sup>he shall dwell on high:</span><br/><span class=\"text Isa-33-16\">his place of defence shall be the munitions of rocks:</span><br/><span class=\"text Isa-33-16\">bread shall be given him; his waters shall be sure.</span></p><span data-line-id='firstreading_fbec1380-3a40-5015-b42f-ca68cbb642da'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-33-17\" id=\"en-AKJV-18297\"><sup class=\"versenum\">17\u00a0</sup>Thine eyes shall see the king in his beauty:</span><br/><span class=\"text Isa-33-17\">they shall behold the land that is very far off.</span><br/><span class=\"text Isa-33-18\" id=\"en-AKJV-18298\"><sup class=\"versenum\">18\u00a0</sup>Thine heart shall meditate terror.</span><br/><span class=\"text Isa-33-18\">Where is the scribe?</span><br/><span class=\"text Isa-33-18\">where is the receiver?</span><br/><span class=\"text Isa-33-18\">where is he that counted the towers?</span><br/><span class=\"text Isa-33-19\" id=\"en-AKJV-18299\"><sup class=\"versenum\">19\u00a0</sup>Thou shalt not see a fierce people,</span><br/><span class=\"text Isa-33-19\">a people of a deeper speech than thou canst perceive;</span><br/><span class=\"text Isa-33-19\">of a stammering tongue, that thou canst not understand.</span><br/><span class=\"text Isa-33-20\" id=\"en-AKJV-18300\"><sup class=\"versenum\">20\u00a0</sup>Look upon Zion, the city of our solemnities:</span><br/><span class=\"text Isa-33-20\">thine eyes shall see Jerusalem a quiet habitation,</span><br/><span class=\"text Isa-33-20\">a tabernacle that shall not be taken down;</span><br/><span class=\"text Isa-33-20\">not one of the stakes thereof shall ever be removed,</span><br/><span class=\"text Isa-33-20\">neither shall any of the cords thereof be broken.</span><br/><span class=\"text Isa-33-21\" id=\"en-AKJV-18301\"><sup class=\"versenum\">21\u00a0</sup>But there the glorious <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> will be unto us a place of broad rivers and streams;</span><br/><span class=\"text Isa-33-21\">wherein shall go no galley with oars,</span><br/><span class=\"text Isa-33-21\">neither shall gallant ship pass thereby.</span><br/><span class=\"text Isa-33-22\" id=\"en-AKJV-18302\"><sup class=\"versenum\">22\u00a0</sup>For the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is our judge, the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is our lawgiver,</span><br/><span class=\"text Isa-33-22\">the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is our king; he will save us.</span><br/><span class=\"text Isa-33-23\" id=\"en-AKJV-18303\"><sup class=\"versenum\">23\u00a0</sup>Thy tacklings are loosed;</span><br/><span class=\"text Isa-33-23\">they could not well strengthen their mast,</span><br/><span class=\"text Isa-33-23\">they could not spread the sail:</span><br/><span class=\"text Isa-33-23\">then is the prey of a great spoil divided;</span><br/><span class=\"text Isa-33-23\">the lame take the prey.</span><br/><span class=\"text Isa-33-24\" id=\"en-AKJV-18304\"><sup class=\"versenum\">24\u00a0</sup>And the inhabitant shall not say, I am sick:</span><br/><span class=\"text Isa-33-24\">the people that dwell therein shall be forgiven their iniquity.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 4:31-44"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the fourth chapter, the thirty-first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_955aff50-2dd2-5bec-bcf2-bdb43451648f'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p> <span class=\"text Luke-4-31\" id=\"en-AKJV-25095\"><sup class=\"versenum\">31\u00a0</sup>and came down to Capernaum, a city of Galilee, and taught them on the sabbath days. </span> <span class=\"text Luke-4-32\" id=\"en-AKJV-25096\"><sup class=\"versenum\">32\u00a0</sup>And they were astonished at his doctrine: for his word was with power.</span></p><span data-line-id='secondreading_c48f8289-a5e8-5137-a349-480368a9b017'></span> <p><span class=\"text Luke-4-33\" id=\"en-AKJV-25097\"><sup class=\"versenum\">33\u00a0</sup>And in the synagogue there was a man, which had a spirit of an unclean devil, and cried out with a loud voice, </span> <span class=\"text Luke-4-34\" id=\"en-AKJV-25098\"><sup class=\"versenum\">34\u00a0</sup>saying, Let us alone; what have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art; the Holy One of God. </span> <span class=\"text Luke-4-35\" id=\"en-AKJV-25099\"><sup class=\"versenum\">35\u00a0</sup>And Jesus rebuked him, saying, Hold thy peace, and come out of him. And when the devil had thrown him in the midst, he came out of him, and hurt him not. </span> <span class=\"text Luke-4-36\" id=\"en-AKJV-25100\"><sup class=\"versenum\">36\u00a0</sup>And they were all amazed, and spake among themselves, saying, What a word is this! for with authority and power he commandeth the unclean spirits, and they come out. </span> <span class=\"text Luke-4-37\" id=\"en-AKJV-25101\"><sup class=\"versenum\">37\u00a0</sup>And the fame of him went out into every place of the country round about.</span></p><span data-line-id='secondreading_6c5eae98-90d9-5430-af7b-f5825967bc66'></span> <p><span class=\"text Luke-4-38\" id=\"en-AKJV-25102\"><sup class=\"versenum\">38\u00a0</sup>And he arose out of the synagogue, and entered into Simon\u2019s house. And Simon\u2019s wife\u2019s mother was taken with a great fever; and they besought him for her. </span> <span class=\"text Luke-4-39\" id=\"en-AKJV-25103\"><sup class=\"versenum\">39\u00a0</sup>And he stood over her, and rebuked the fever; and it left her: and immediately she arose and ministered unto them.</span></p><span data-line-id='secondreading_e63e6189-efcf-5551-ace9-8da2b0bafad8'></span> <p><span class=\"text Luke-4-40\" id=\"en-AKJV-25104\"><sup class=\"versenum\">40\u00a0</sup>Now when the sun was setting, all they that had any sick with divers diseases brought them unto him; and he laid his hands on every one of them, and healed them. </span> <span class=\"text Luke-4-41\" id=\"en-AKJV-25105\"><sup class=\"versenum\">41\u00a0</sup>And devils also came out of many, crying out, and saying, Thou art Christ the Son of God. And he rebuking them suffered them not to speak: for they knew that he was Christ.</span></p><span data-line-id='secondreading_7b06b0e3-cd16-50e6-8d72-4d151532bd70'></span> <p><span class=\"text Luke-4-42\" id=\"en-AKJV-25106\"><sup class=\"versenum\">42\u00a0</sup>And when it was day, he departed and went into a desert place: and the people sought him, and came unto him, and stayed him, that he should not depart from them. </span> <span class=\"text Luke-4-43\" id=\"en-AKJV-25107\"><sup class=\"versenum\">43\u00a0</sup>And he said unto them, I must preach the kingdom of God to other cities also: for therefore am I sent. </span> <span class=\"text Luke-4-44\" id=\"en-AKJV-25108\"><sup class=\"versenum\">44\u00a0</sup>And he preached in the synagogues of Galilee.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Friday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Edmund, King of East Anglia and Martyr, 870"},{"line_type":"leader","content":"Almighty God, you gave your servant Edmund boldness to confess the Name of our Savior Jesus Christ before the rulers of this world, and courage to die for this faith: Grant that we may always be ready to give a reason for the hope that is in us, and to suffer gladly for the sake of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Faith"},{"line_type":"subheading","content":"Friday"},{"line_type":"leader","content":"Lord Jesus Christ, by your death you took away the sting of death: Grant to us your servants so to follow in faith where you have led the way, that we may at length fall asleep peacefully in you and wake up in your likeness; for your tender mercies' sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God and Father of all, whom the whole heavens adore: Let the whole earth also worship you, all nations obey you, all tongues confess and bless you, and men, women, and children everywhere love you and serve you in peace; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Glory to God whose power, working in us, can do infinitely more than we can ask or imagine: Glory to him from generation to generation in the Church, and in Christ Jesus for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"EPHESIANS 3:20-21"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"You, O Lord, are in the midst of us, and we are called by your name; do not leave us."},{"line_type":"citation","content":"JEREMIAH 14:9"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Aid Against Peril"},{"line_type":"leader","content":"Lighten our darkness, we beseech you, O Lord; and by your great mercy defend us from all perils and dangers of this night; for the love of your only Son, our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Be present, O merciful God, and protect us through the hours of this night, so that we who are wearied by the changes and chances of this life may rest in your eternal changelessness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"O God, your unfailing providence sustains the world we live in and the life we live: Watch over those, both night and day, who work while others sleep, and grant that we may never forget that our common life depends upon each other\u2019s toil; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
